// Logic gates: four LEDs show what two switches make.
// The port map (Vivado's XDC file) puts sw on the 16 switches and led on the 16 LEDs.
module top (
  input  [15:0] sw,    // the 16 slide switches, up = 1
  output [15:0] led    // the 16 green LEDs, 1 = on
);
  assign led[0] = sw[0] & sw[1];   // AND: lit when both are up
  assign led[1] = sw[0] | sw[1];   // OR:  lit when either is up
  assign led[2] = sw[0] ^ sw[1];   // XOR: lit when exactly one is up
  assign led[3] = ~sw[0];          // NOT: lit while SW0 is down

  // LD4-LD15 simply follow their switches.
  assign led[15:4] = sw[15:4];
endmodule
